import { Buffer } from "node:buffer";
import { describe, expect, it, vi } from "vitest";
import { sqliteBinary, sqliteNoCase } from "./sidebar-local-order";

describe("SQLite binary ordering", () => {
  it("matches UTF-8 byte ordering across prefixes and Unicode planes", () => {
    const values = [
      "",
      "a",
      "aa",
      "z",
      "\0",
      "\0a",
      "é",
      "e\u0301",
      "\ud7ff",
      "\ue000",
      "\uffff",
      "😀",
      "😁",
      "𠀀",
      "\u{10ffff}",
      "a😀",
      "a😀z",
      "a\ue000",
    ];
    for (const left of values) {
      for (const right of values) {
        expect(Math.sign(sqliteBinary(left, right)), JSON.stringify([left, right])).toBe(
          Math.sign(Buffer.compare(Buffer.from(left, "utf8"), Buffer.from(right, "utf8"))),
        );
      }
    }
  });

  it.each([
    ["\ud800", "\ud801", -1],
    ["\udfff", "\ue000", -1],
    ["\ud800x", "𐀀", -1],
    ["😀\ud800", "😀\ud801", -1],
    ["😀", "😀x", -1],
  ])("preserves code-point ordering for %j and %j", (left, right, order) => {
    expect(Math.sign(sqliteBinary(left, right))).toBe(order);
    expect(Math.sign(sqliteBinary(right, left))).toBe(-order);
  });

  it("does not inspect either suffix after the first code-point difference", () => {
    const left = "b" + "😀".repeat(10_000);
    const right = "a" + "\ue000".repeat(10_000);
    const readPoint = vi.spyOn(String.prototype, "codePointAt");
    let result: number;
    let reads: number;
    try {
      result = sqliteBinary(left, right);
      reads = readPoint.mock.calls.length;
    } finally {
      readPoint.mockRestore();
    }
    expect(result).toBeGreaterThan(0);
    expect(reads).toBeLessThanOrEqual(2);
  });

  it("keeps SQLite NOCASE limited to ASCII case folding", () => {
    expect(sqliteNoCase("Alpha", "alpha")).toBe(0);
    expect(sqliteNoCase("Ä", "ä")).toBeLessThan(0);
    expect(sqliteNoCase("😀A", "😀a")).toBe(0);
    expect(sqliteNoCase("\ufffd", "😀")).toBeLessThan(0);
  });
});

